const DATA = {"meta": {"version": "2.0.0", "total_dimensions": 12, "explicit_dimensions": 5, "orthogonal_dimensions": 7, "curated_sentences_count": 6, "weakness_drill_archetypes": 5, "morpheme_kb_entries": 13, "participle_kb_entries": 4}, "dimensions": [{"id": "D01", "type": "显式升维", "name": "四档变速与意群换气朗读", "vs_google": "Google 仅机械连读+无用中文拼音；本舱提供 0.65x~1.2x 四档语速、意群停顿符(/, ||)与重音核点读"}, {"id": "D02", "type": "显式升维", "name": "主干脱水与五层从句染色树", "vs_google": "Google 黑盒直出译文；本舱剥离 48 词修饰壳至 9 词主干，可视化染色主语从句/双表语从句/定语从句"}, {"id": "D03", "type": "显式升维", "name": "8390一词一义核与611词根拆解", "vs_google": "Google 无单字词源；本舱联动 8,390 词库动态核与词根前缀后缀(如 dis+pro+port+ion+ate+ly)+同根词串记"}, {"id": "D04", "type": "显式升维", "name": "分词、非谓语与不规则变形实验室", "vs_google": "Google 不提示语法陷阱；本舱专项解剖 borne(bear过去分词 vs born)、evolving(现在分词)、getting(动名词)、to influence(后置不定式)"}, {"id": "D05", "type": "显式升维", "name": "高频固定考试搭配与语块提炼", "vs_google": "Google 不提炼考点词块；本舱提取 not merely that...but that / be borne disproportionately by 等 6 大完形写作王牌词块"}, {"id": "D06", "type": "正交突围", "name": "命题人设题暗号与仿真阅读题破译", "vs_google": "正交盲区1：长难句 95% 是阅读出题点！精准标定『not merely陪衬 vs but主旨靶心』并附带四选一真题陷阱演练"}, {"id": "D07", "type": "正交突围", "name": "代词指代链与连接词省略恢复", "vs_google": "正交盲区2：考生常死于小词！穿透解析 getting it wrong 中 it 指代、by those who 中 those 指代及双 that 不可省定律"}, {"id": "D08", "type": "正交突围", "name": "考研翻译四步拆分与 4×0.5分采分点", "vs_google": "正交盲区3：给出『英语顺译切块 → 汉语左分支调序规则 → 阅卷人 4×0.5 分采分点核对单』"}, {"id": "D09", "type": "正交突围", "name": "高分写作句式模具与三母题迁移仿写", "vs_google": "正交盲区4：输入端精读直接转化为输出端考研大作文/雅思 Task 2 满分句型模具与跨话题仿写"}, {"id": "D10", "type": "正交突围", "name": "由简入繁四阶逆向生长树 (9→48词)", "vs_google": "正交盲区5：动态演示 9 词简单句如何分 4 步挂载从句、比较结构与分词短语长成 48 词真题完全体"}, {"id": "D11", "type": "正交突围", "name": "语篇衔接功能与上下文走向预测", "vs_google": "正交盲区6：服务考研新题型(七选五/排序)与雅思段落匹配，反推前文铺垫并预测后文必然展开方向"}, {"id": "D12", "type": "正交突围", "name": "三模主动回忆内化闭环 (挖空/重组/回译)", "vs_google": "正交盲区7：破除『看译文假懂』幻觉，提供连接词分词挖空、6意群乱序重组、看中说英回译三阶实战"}], "sentences": [{"id": "LS_01_AI_REGULATION", "title": "🔥 旗舰样板 #1（用户截图原句）：人工智能监管困境与弱势群体风险失衡 (48词 · 三考最高频复合骨架)", "source_tag": "🎯 用户截图原句 · The Economist / 2027考研英语一 & IELTS 8.0 同源社论", "word_count": 48, "char_count": 291, "difficulty": "★★★★★ (IELTS 8.5 / 考研英语一翻译满分级)", "raw_en": "What makes the debate over artificial intelligence so difficult is not merely that the technology is evolving faster than regulators can respond, but that the consequences of getting it wrong are likely to be borne disproportionately by those who have the least power to influence the rules.", "google_raw_zh": "围绕人工智能的辩论之所以如此棘手，不仅在于该技术的发展速度超出了监管机构的应对能力，更在于一旦决策失误，其后果很可能会不成比例地由那些在规则制定方面最缺乏影响力的人群来承担。", "google_defect_diagnosis": "Google 翻译仅给出黑盒终态中文与毫无意义的汉语拼音 (Wéirào réngōng...)，考生看完误以为『懂了』，但合上中文依然找不出 48 词的系动词主轴 `is`，分不清两个 `that` 的并列层级，看不出 `borne` 是 `bear` 的过去分词，更抓不住 `not merely...but...` 背后的阅读必考设题陷阱。", "d01_prosody": {"chunked_en": "[1] ●What makes the debate / over artificial intelligence / so ●difficult || [2] is ●not ●merely that / the technology is ●evolving faster / than regulators can ●respond, || [3] ●but that / the ●consequences of getting it ●wrong / are likely to be ●borne ●disproportionately || [4] by ●those / who have the ●least power / to ●influence the ●rules.", "breath_groups": [{"chunk": "What makes the debate over artificial intelligence so difficult", "zh": "是什么让围绕人工智能的争论如此棘手", "role": "🟦 主语从句 (Subject Clause)", "pause_after": "|| (长停顿 0.45s · 主语结束，准备迎接全句核心系动词 is)"}, {"chunk": "is not merely that the technology is evolving faster than regulators can respond,", "zh": "不仅仅是因为这项技术演进得比监管机构所能反应的速度更快，", "role": "🟨 系动词 + 表语从句① + 比较从句", "pause_after": "|| (长停顿 0.50s · 让步陪衬层结束，准备蓄力重读转折核 but)"}, {"chunk": "but that the consequences of getting it wrong are likely to be borne disproportionately", "zh": "更是因为一旦把事情搞砸，其后果很可能会不成比例地被承担——", "role": "🟪 表语从句②核心 (被动语态 + 程度副词)", "pause_after": "/ (微停顿 0.25s · 引出被动动作的承受者 by those)"}, {"chunk": "by those who have the least power to influence the rules.", "zh": "由那些最没有能力去影响规则制定的人群来承担。", "role": "🟥 施事介词短语 + 定语从句 + 不定式后置定语", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "What makes the debate difficult is not merely that [Clause A], but that [Clause B].", "trunk_zh": "【极简九词主干】[让这场辩论如此困难的根源] (S) + [是] (V) + [不仅在于原因A，更在于原因B] (P1 & P2)。", "layers": [{"level": "L1 全句主干 (Main Trunk)", "color": "#2563eb", "segment": "What makes the debate ... so difficult [S] + is [V] + not merely that... , but that... [P1 & P2]", "function": "主系表大骨架：`What` 引导的主语从句充当全句主语，系动词 `is` 后接由 `not merely... but...` 并列连接的两个 `that` 表语从句。"}, {"level": "L2 主语从句内部 (Inside Subject Clause)", "color": "#0284c7", "segment": "What [主] + makes [谓] + the debate (over artificial intelligence) [宾 + 介词后置定语] + so difficult [宾补]", "function": "`make + 宾语 + 形容词宾补` 结构（使……变得如此困难），其中 `over artificial intelligence` 限定 `debate` 的议题。"}, {"level": "L3 第一表语从句 + 比较状语从句 (Predicative Clause 1)", "color": "#d97706", "segment": "not merely that + the technology is evolving [主谓] + faster than regulators can respond [比较状语从句]", "function": "交代第一层表象原因（技术迭代速度 > 监管响应速度），在考试阅读中属于『次要陪衬信息』。"}, {"level": "L4 第二表语从句 + 动名词与被动谓语 (Predicative Clause 2 · 全句重心)", "color": "#7c3aed", "segment": "but that + the consequences (of getting it wrong) [主 + 介宾定语] + are likely to be borne disproportionately [复合被动谓语]", "function": "全句核心论点落脚点！`of getting it wrong` 限定后果的来源，`are likely to be borne` 为 `be likely to do` 与被动语态 `be borne` 的嵌套。"}, {"level": "L5 施事短语 + 定语从句 + 不定式链 (Relative & Infinitive Tail)", "color": "#e11d48", "segment": "by those [介宾] + who have the least power [定语从句修饰 those] + to influence the rules [不定式修饰 power]", "function": "典型的英语『右分支尾重结构 (End-Weight)』：一层套一层向右侧延伸，点明真正为失误买单的弱势群体。"}]}, "d05_collocations": [{"chunk": "the debate over / surrounding sth.", "zh": "围绕……的争论/辩论", "exam_use": "考研阅读高频起兴词块；写作可替换 the controversy concerning..."}, {"chunk": "not merely that... , but (also) that...", "zh": "不仅在于……，更在于……", "exam_use": "连接两个并列主语/宾语/表语从句的高阶递进结构，比 not only...but also 更具学术书面感"}, {"chunk": "evolve faster than sb. can respond", "zh": "演进速度超出某人的应对能力", "exam_use": "科技类话题（AI/生物技术/算法监管）黄金比较句块"}, {"chunk": "the consequences of getting it wrong", "zh": "一旦出错/决策失误所带来的后果", "exam_use": "get it wrong 为地道习语式动名词短语，在学术政论文中四两拨千斤"}, {"chunk": "be likely to be borne disproportionately by...", "zh": "很可能不成比例地由……来承担", "exam_use": "bear the consequences / cost / burden 固定搭配的被动升格版 + disproportionately 极性副词"}, {"chunk": "have the least power to influence the rules", "zh": "最缺乏影响规则制定的话语权/能力", "exam_use": "the least + 抽象名词 + to do，精准刻画权力或资源分配的不对称性"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【not merely A, but B 递进重心律】：考官百分之百会在 B（即后果由最无话语权群体不成比例承担）设正确选项，而用 A（技术发展太快监管跟不上）制作『以偏概全 / 偷换重心』的强干扰项！", "🚨 信号 2【disproportionately 极性副词靶点】：雅思 8.0 与考研阅读正确选项必将其同义替换为 `unevenly distributed / unfairly shouldered / asymmetrically affecting`。", "🚨 信号 3【those who have the least power 弱势群体替换】：正确选项常整体概括为 `marginalized groups / vulnerable populations / people excluded from decision-making`。"], "mcq_question": "According to the sentence, why is the controversy surrounding artificial intelligence particularly thorny?", "mcq_options": [{"opt": "A", "text": "Because regulatory agencies completely lack the technical expertise to understand how AI evolves.", "is_correct": false, "analysis": "❌ 典型干扰项（无中生有 + 曲解比较级）：原文仅说技术演进快于监管响应 (`evolving faster than regulators can respond`)，并未说监管机构『完全缺乏理解 AI 的技术专业知识』。"}, {"opt": "B", "text": "Primarily because technological iteration outpaces legislative procedures in most jurisdictions.", "is_correct": false, "analysis": "❌ 典型强干扰项（错把 not merely 陪衬当重心）：虽然提到了速度超过监管，但这只是 `not merely` 的前半句铺垫，而选项用了 `Primarily (主要因为)`，直接违背了原文 `but that` 的真正重心！"}, {"opt": "C", "text": "Because besides the rapid pace of tech evolution, the cost of regulatory failure falls unfairly on groups with minimal say in rulemaking.", "is_correct": true, "analysis": "✅ 正确选项（完美同义替换）：`besides the rapid pace` 对应 `not merely...evolving faster`；`cost of regulatory failure` 对应 `consequences of getting it wrong`；`falls unfairly on` 对应 `borne disproportionately by`；`minimal say in rulemaking` 完美替换 `least power to influence the rules`！"}, {"opt": "D", "text": "Because those who formulate the rules intentionally shift all technological risks onto ordinary citizens.", "is_correct": false, "analysis": "❌ 典型干扰项（主观臆断恶意动机）：原文说『很可能不成比例地由最无权影响规则的人承担』，并未说规则制定者是『故意 (intentionally) 转嫁所有风险』。"}]}, "d07_anaphora": [{"pronoun": "What (句首)", "target": "The underlying factor / thing that...", "explanation": "复合关系代词，相当于 `The thing that...`，既引导主语从句又在从句内部充当 `makes` 的主语。"}, {"pronoun": "that ① & that ②", "target": "is not merely [that...] , but [that...]", "explanation": "两个并列的表语从句引导词。⚠️ 语法铁律：当两个表语/宾语从句由 `not merely...but...` 连接时，第二个 `that` 绝对不可省略！"}, {"pronoun": "it (getting it wrong)", "target": "handling / regulating artificial intelligence", "explanation": "指代前文探讨的『应对与监管人工智能这件核心事务』，`get it wrong` 即『在这件事上做出错误决策』。"}, {"pronoun": "those (by those who...)", "target": "people / societal groups", "explanation": "指示代词作介词 `by` 的宾语，泛指『那些特定的人群』，必须借助后面的 `who` 定语从句完足语义。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语思维顺译切块】是什么让关于AI的争论如此困难 ／ 不仅仅是技术正在比监管者能回应的速度更快地演进 ／ 而是把这件事搞错的后果 ／ 很可能会被不成比例地承担 ／ 由那些拥有最少权力去影响规则的人。", "step2_reorder": "【第二步：中文左分支调序法则】① 将 `What makes X so adj. is...` 转化为中文因果话题句『围绕 X 的争论之所以如此……，原因在于……』；② 将 `of getting it wrong` 动名词定语前置化为条件分句『一旦决策失误，其后果……』；③ 将长定语 `who have the least power to influence the rules` 提到『人群』之前，化右分支为左分支。", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`What makes the debate...is not merely that..., but that...` 准确译出『……之所以如此棘手，不仅在于……，更在于……』主从递进逻辑。", "🎯 采分点 2 (0.5分)：`evolving faster than regulators can respond` 准确译出比较结构『演进/发展速度超出了监管机构的应对能力』。", "🎯 采分点 3 (0.5分)：`consequences of getting it wrong are likely to be borne disproportionately` 准确译出『一旦出错的后果很可能不成比例地由……承担』（认出 `borne` = 承担）。", "🎯 采分点 4 (0.5分)：`by those who have the least power to influence the rules` 定语从句前置译为『那些在制定规则方面最缺乏话语权/影响力的人群』。"]}, "d09_writing_formula": {"formula_skeleton": "What makes the debate over [争议议题 X] so difficult is not merely that [表层挑战/速度失控 A], but that the consequences of [失误/放任风险 B] are likely to be borne disproportionately by those who [弱势群体特征 C].", "imitations": [{"topic": "🌿 气候变化与碳中和 (IELTS Writing Task 2 / 考研生态环保母题)", "en": "What makes the debate over global carbon taxation so difficult is not merely that extreme weather is intensifying faster than nations can adapt, but that the consequences of delaying action are likely to be borne disproportionately by developing communities who have the least resources to withstand ecological shocks.", "zh": "围绕全球碳税的争论之所以如此棘手，不仅在于极端天气的恶化速度超出了各国的适应能力，更在于拖延行动的后果很可能会不成比例地由那些最缺乏抵御生态冲击资源的发展中社区来承担。"}, {"topic": "🎓 高等教育与数字鸿沟 (CET-6 六级议论文 / 考研教育文化母题)", "en": "What makes the debate over AI-assisted education so difficult is not merely that pedagogical tools are updating faster than curricula can adjust, but that the consequences of widening the digital divide are likely to be borne disproportionately by rural students who have the least access to premium mentorship.", "zh": "围绕AI辅助教育的争论之所以如此棘手，不仅在于教学工具的更新速度超出了课程体系的调整能力，更在于数字鸿沟扩大的后果很可能会不成比例地由那些最缺乏优质师资指导的偏远地区学生来承担。"}]}, "d10_telescoping": [{"stage": 1, "words": 9, "label": "Stage 1 · 9词青铜主干核", "en": "The debate is not merely Fact A, but Fact B.", "added": "最原始的主系表 + 并列递进骨架"}, {"stage": 2, "words": 20, "label": "Stage 2 · 20词白银主从扩展", "en": "What makes the debate over AI so difficult is not merely that technology evolves fast, but that consequences are borne by people.", "added": "将名词主语升级为 What 主语从句，将 Fact A/B 展开为两个 that 表语从句"}, {"stage": 3, "words": 34, "label": "Stage 3 · 34词黄金比较与被动", "en": "What makes the debate over AI so difficult is not merely that the technology is evolving faster than regulators can respond, but that the consequences are likely to be borne disproportionately by those.", "added": "注入 faster than 比较状语从句 + are likely to be borne 被动不定式 + disproportionately 极性副词"}, {"stage": 4, "words": 48, "label": "Stage 4 · 48词王者真题完全体", "en": "What makes the debate over artificial intelligence so difficult is not merely that the technology is evolving faster than regulators can respond, but that the consequences of getting it wrong are likely to be borne disproportionately by those who have the least power to influence the rules.", "added": "挂载 of getting it wrong 动名词定语 + who have the least power to influence the rules 定语从句与不定式链"}], "d11_discourse": {"prior_para": "【前文必然铺垫】阐述生成式 AI 与算法技术在各行业爆炸式落地，各国政府与科技巨头围绕『如何立法监管 AI』展开激烈交锋但迟迟难以达成共识。", "current_role": "【本句语篇枢纽】承上启下的『问题定性+立意升维句』——作者用 `not merely...but...` 将讨论从单纯的『技术迭代快 vs 立法慢（效率问题）』一举拔高到『权力不对称与风险分配不公（社会正义问题）』。", "next_para": "【后文必然展开】必将具体举例说明哪些弱势群体（如低技能劳动者、缺乏申诉渠道的普通公民）正在承受算法偏见或监管失误的代价，或提出让公众参与规则制定的治理建议（考研新题型七选五/排序题核心锁扣）！"}}, {"id": "LS_02_KAOYAN_2024", "title": "🎓 经典样板 #2（考研英语一真题级）：科学怀疑精神与算法同行评审 (39词 · 让步从句 + 被动复合结构)", "source_tag": "🎓 2027考研英语一核心样板 · 科技哲学与学术治理", "word_count": 39, "char_count": 264, "difficulty": "★★★★☆ (考研英语一阅读 Part A & 翻译必考型)", "raw_en": "Although automated algorithms now screen thousands of manuscripts before human editors ever see them, many veteran scholars still harbor deep skepticism toward purely quantitative evaluation metrics that fail to capture original theoretical breakthroughs.", "google_raw_zh": "尽管自动算法现在在人类编辑看到数千份手稿之前对其进行筛选，但许多资深学者仍然对无法捕捉原始理论突破的纯定量评估指标怀有深深的怀疑。", "google_defect_diagnosis": "直译腔严重（『在人类编辑看到数千份手稿之前对其进行筛选』绕口生硬），且未揭示 `screen (网筛过滤 K08)` 与 `harbor (海港收容→心怀暗藏 K05)` 两大熟词僻义及 `Although` 主从重心法则。", "d01_prosody": {"chunked_en": "[1] ●Although automated algorithms / now ●screen thousands of manuscripts / before human editors ●ever see them, || [2] many veteran ●scholars / still ●harbor deep ●skepticism / toward purely ●quantitative evaluation metrics || [3] that ●fail to capture / ●original theoretical ●breakthroughs.", "breath_groups": [{"chunk": "Although automated algorithms now screen thousands of manuscripts before human editors ever see them,", "zh": "尽管自动化算法如今在人工编辑审阅前就已初筛了成千上万篇稿件，", "role": "🟨 Although 让步状语从句 + before 时间从句", "pause_after": "|| (长停顿 0.45s · 让步从句结束，主句才是核心)"}, {"chunk": "many veteran scholars still harbor deep skepticism toward purely quantitative evaluation metrics", "zh": "许多资深学者依然对纯量化的评价指标心存深深疑虑——", "role": "🟦 全句主干 (S + V + O + 介宾短语)", "pause_after": "/ (微停顿 0.25s · 引出修饰 metrics 的定语从句)"}, {"chunk": "that fail to capture original theoretical breakthroughs.", "zh": "因为这类指标无法捕捉到原创性的理论突破。", "role": "🟥 that 定语从句 (原因化译法)", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "Many scholars still harbor skepticism toward evaluation metrics.", "trunk_zh": "【极简八词主干】[许多学者] (S) + [依然心怀] (V: harbor) + [怀疑态度] (O: skepticism) + [针对评价指标] (Adv)。", "layers": [{"level": "L1 让步状语从句 (Concessive Clause)", "color": "#d97706", "segment": "Although automated algorithms now screen thousands of manuscripts (before human editors ever see them)", "function": "`Although` 引导让步状语，内部嵌套 `before` 时间从句；`screen` 此处作动词表『过筛过滤』。"}, {"level": "L2 主句核心主谓宾 (Main Trunk · 全句重心)", "color": "#2563eb", "segment": "many veteran scholars [主] + still harbor [谓] + deep skepticism [宾] + toward purely quantitative evaluation metrics [介宾]", "function": "主句核心：`harbor` 由名词『海港』动化为『在内心收容/怀有（疑虑、敌意）』。"}, {"level": "L3 限制性定语从句 (Relative Clause)", "color": "#e11d48", "segment": "that fail to capture original theoretical breakthroughs", "function": "修饰先行词 `metrics`，点明学者怀疑的根本原因。"}]}, "d05_collocations": [{"chunk": "screen thousands of manuscripts", "zh": "筛查/初筛数千篇手稿", "exam_use": "screen 作动词表过滤筛查，高频熟词僻义"}, {"chunk": "harbor deep skepticism toward...", "zh": "对……心怀深深的怀疑", "exam_use": "harbor doubts / skepticism / resentment 考研与雅思 C2 级高分动宾搭配"}, {"chunk": "purely quantitative evaluation metrics", "zh": "纯量化的评估指标", "exam_use": "学术评价与教育改革类话题核心名词簇"}, {"chunk": "fail to capture original breakthroughs", "zh": "未能捕捉到原创性突破", "exam_use": "capture 在学术语境中表『准确反映/捕捉（精髓/特征）』"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【Although 让步转折律】：`Although` 从句承认算法审稿效率高，但主句 `still harbor deep skepticism` 才是作者态度靶心（态度题必选 skeptical / critical / cautious）！", "🚨 信号 2【熟词僻义双连击】：同句连考 `screen (筛查)` 与 `harbor (心怀)` 两个核心熟词僻义。"], "mcq_question": "What is the veteran scholars' attitude toward algorithmic and purely quantitative peer review?", "mcq_options": [{"opt": "A", "text": "Enthusiastic about its efficiency in reducing human editors' workload.", "is_correct": false, "analysis": "❌ 错把 Although 让步部分当主句态度，且原文未说学者对此充满热情。"}, {"opt": "B", "text": "Reserved and doubtful because it overlooks groundbreaking theoretical innovation.", "is_correct": true, "analysis": "✅ `Reserved and doubtful` 对应 `harbor deep skepticism`；`overlooks groundbreaking theoretical innovation` 对应 `fail to capture original theoretical breakthroughs`！"}, {"opt": "C", "text": "Completely opposed to any use of computers in manuscript submission.", "is_correct": false, "analysis": "❌ 极端绝对化干扰项 (`Completely opposed to any use`)。"}, {"opt": "D", "text": "Indifferent since human editors still make the final decision.", "is_correct": false, "analysis": "❌ `Indifferent (漠不关心)` 属于考研态度题万年陪跑错项。"}]}, "d07_anaphora": [{"pronoun": "them (ever see them)", "target": "thousands of manuscripts", "explanation": "复数人称代词宾格，回指前面被算法初筛的『数千篇手稿』。"}, {"pronoun": "that (that fail to capture)", "target": "purely quantitative evaluation metrics", "explanation": "关系代词指代复数先行词 `metrics`，故从句谓语用复数 `fail`。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语顺译】尽管自动算法现在筛查数千手稿／在人类编辑看到它们之前／许多资深学者仍然怀有深深怀疑／对纯量化评估指标／那些未能捕捉原创理论突破的指标。", "step2_reorder": "【第二步：调序精炼】将 `before` 时间状语提至 `screen` 之前译为『在人工编辑审阅前就已对数千篇稿件进行了初筛』；将末尾 `that` 定语从句转化为原因补述或前置定语。", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`screen` 译为『筛查/初筛』而非『屏幕』。", "🎯 采分点 2 (0.5分)：`harbor deep skepticism` 译为『心怀/抱有深深疑虑』而非『海港』。", "🎯 采分点 3 (0.5分)：`purely quantitative evaluation metrics` 译为『纯量化的评价指标』。", "🎯 采分点 4 (0.5分)：`fail to capture original theoretical breakthroughs` 译为『无法捕捉原创性理论突破』。"]}, "d09_writing_formula": {"formula_skeleton": "Although [新兴技术/制度 A] now [效率优势 B] before [传统主体 C], many veteran observers still harbor deep skepticism toward [单一化弊端 D] that fail to capture [核心人文/本质价值 E].", "imitations": [{"topic": "🤖 标准化考试与人才选拔 (考研/六级教育话题)", "en": "Although standardized tests now evaluate millions of applicants efficiently, many educators still harbor deep skepticism toward purely score-driven admissions that fail to capture students' creative resilience.", "zh": "尽管标准化考试如今能高效评估数百万申请者，但许多教育者依然对无法衡量学生创新韧性的纯唯分数论录取抱有深深疑虑。"}]}, "d10_telescoping": [{"stage": 1, "words": 7, "label": "Stage 1 · 7词主干", "en": "Scholars still harbor skepticism toward metrics.", "added": "最简主谓宾骨架"}, {"stage": 2, "words": 18, "label": "Stage 2 · 18词加定语从句", "en": "Many veteran scholars still harbor deep skepticism toward purely quantitative metrics that fail to capture breakthroughs.", "added": "注入形容词修饰与 that 定语从句"}, {"stage": 3, "words": 31, "label": "Stage 3 · 31词加让步状语从句", "en": "Although automated algorithms now screen thousands of manuscripts, many veteran scholars still harbor deep skepticism toward purely quantitative evaluation metrics that fail to capture breakthroughs.", "added": "前置 Although 让步状语从句形成对比张力"}, {"stage": 4, "words": 39, "label": "Stage 4 · 39词真题完全体", "en": "Although automated algorithms now screen thousands of manuscripts before human editors ever see them, many veteran scholars still harbor deep skepticism toward purely quantitative evaluation metrics that fail to capture original theoretical breakthroughs.", "added": "嵌入 before 时间状语从句与完整学术修饰词"}], "d11_discourse": {"prior_para": "【前文铺垫】介绍各大期刊出版社纷纷引入 AI 初审系统以应对投稿量激增。", "current_role": "【本句功能】转折立论句——指出自动化与量化指标虽快，但在识别颠覆性原创成果上存在结构性盲区。", "next_para": "【后文走向】列举历史上差点被量化指标拒稿的诺奖级非共识论文案例，倡导『人机协同+定性同行评议』。"}}, {"id": "LS_03_IELTS_INVERSION", "title": "🌍 经典样板 #3（IELTS 剑雅阅读 8.5 级）：否定词置首部分倒装与生态链制衡 (41词 · Not until 倒装 + 分词结果状语)", "source_tag": "🌍 IELTS Academic Reading Band 8.5 · 生态学与物种制衡", "word_count": 41, "char_count": 269, "difficulty": "★★★★★ (IELTS 阅读 T/F/NG 与段落信息匹配高频倒装句)", "raw_en": "Not until apex predators were systematically reintroduced into the degraded valley did ecologists observe how rapidly natural grazing pressures could hold herbivore populations in check, restoring riverbank vegetation that had been eroded for decades.", "google_raw_zh": "直到顶级捕食者被系统地重新引入退化的山谷，生态学家才观察到自然放牧压力如何迅速抑制食草动物种群，恢复被侵蚀了数十年的河岸植被。", "google_defect_diagnosis": "未提示 `Not until...did ecologists observe` 否定词置首引起的主句部分倒装（考生常把 `did` 误判为疑问句），且漏掉 `observe (K12 凝视观测)`、`hold...in check (K02 截停控制)` 与现在分词 `restoring` 作自然结果状语。", "d01_prosody": {"chunked_en": "[1] ●Not until apex predators / were systematically ●reintroduced into the degraded valley || [2] ●did ecologists ●observe / how rapidly natural grazing pressures / could ●hold herbivore populations in ●check, || [3] ●restoring riverbank vegetation / that had been ●eroded for ●decades.", "breath_groups": [{"chunk": "Not until apex predators were systematically reintroduced into the degraded valley", "zh": "直到顶级捕食者被系统性地重新引入这片退化的山谷，", "role": "🟨 Not until 时间状语从句前置 (触发主句倒装)", "pause_after": "|| (长停顿 0.45s · 倒装触发点，紧接着助动词 did 提前)"}, {"chunk": "did ecologists observe how rapidly natural grazing pressures could hold herbivore populations in check,", "zh": "生态学家们才观测到自然觅食威慑力竟能如此迅速地把食草动物数量控制在安全线内，", "role": "🟦 部分倒装主句 (did + S + V) + how 宾语从句", "pause_after": "|| (长停顿 0.40s · 引出自然而然的生态恢复结果)"}, {"chunk": "restoring riverbank vegetation that had been eroded for decades.", "zh": "进而恢复了此前已被侵蚀数十年的河岸植被。", "role": "🟪 现在分词作结果状语 + that 过去完成时定语从句", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "Ecologists did not observe [how Clause] until predators were reintroduced.", "trunk_zh": "【正常语序还原主干】[生态学家] (S) + [直到捕食者被重新引入才观测到] (V) + [自然压力如何控制种群] (O)。", "layers": [{"level": "L1 前置否定时间从句 (Fronted Negative Clause)", "color": "#d97706", "segment": "Not until apex predators were systematically reintroduced (into the degraded valley)", "function": "将正常语序 `Ecologists did not observe... until...` 中的 `Not until...` 整个提至句首强调时间拐点。"}, {"level": "L2 部分倒装主句 + 宾语从句 (Partial Inversion Main Clause)", "color": "#2563eb", "segment": "did ecologists observe [倒装主谓] + how rapidly natural grazing pressures could hold herbivore populations in check [宾语从句]", "function": "主句将过去时助动词 `did` 提到主语 `ecologists` 之前构成部分倒装；宾语从句含王牌短语 `hold...in check`。"}, {"level": "L3 现在分词结果状语 + 定语从句 (Participial Result & Relative Clause)", "color": "#10b981", "segment": "restoring riverbank vegetation + (that had been eroded for decades)", "function": "`restoring...` 为现在分词短语作顺承结果状语（进而恢复了……），内部嵌套过去完成被动定语从句。"}]}, "d05_collocations": [{"chunk": "Not until [Clause A] did [S + V]...", "zh": "直到……才……（句首部分倒装王牌句型）", "exam_use": "考研写作/翻译与雅思 8.0 必会最高频倒装结构"}, {"chunk": "be systematically reintroduced into...", "zh": "被系统性地重新引入……", "exam_use": "生态保护与政策干预类学术高频被动表达"}, {"chunk": "hold ... in check", "zh": "将……截停控制在合理范围内 / 遏制", "exam_use": "check (K02 截停卡控) 核心必考短语"}, {"chunk": ", restoring ... that had been eroded", "zh": "进而恢复了此前被侵蚀的……（分词作结果状语）", "exam_use": "逗号 + V-ing 表主句动作带来的自然结果，比 and restored 更紧凑高级"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【Not until 倒装时间先后陷阱】：IELTS T/F/NG 最爱设问『Ecologists knew how fast grazing pressures worked BEFORE reintroducing predators (FALSE)』——`Not until` 铁证表明是在重新引入**之后**才观测到！", "🚨 信号 2【restoring 分词因果链】：河岸植被恢复是捕食者控制食草动物种群所引发的**连锁积极结果**。"], "mcq_question": "What can be inferred from the sentence about the valley's ecosystem?", "mcq_options": [{"opt": "A", "text": "Ecologists accurately predicted the exact speed of vegetation recovery prior to the reintroduction program.", "is_correct": false, "analysis": "❌ 与 `Not until...did ecologists observe` 直接矛盾（引入后才观测到有多快）。"}, {"opt": "B", "text": "The return of top predators triggered a trophic cascade that curbed overgrazing and revived damaged riverside plants.", "is_correct": true, "analysis": "✅ `return of top predators` 对应 `apex predators were reintroduced`；`curbed overgrazing` 对应 `hold herbivore populations in check`；`revived damaged riverside plants` 对应 `restoring riverbank vegetation`！"}, {"opt": "C", "text": "Riverbank erosion had already stopped several decades before the predators returned.", "is_correct": false, "analysis": "❌ 曲解 `had been eroded for decades`（此前已被持续侵蚀数十年，而非几十年前就停止了）。"}, {"opt": "D", "text": "Herbivore populations were completely wiped out after apex predators entered the valley.", "is_correct": false, "analysis": "❌ 曲解 `hold...in check (控制在合理范围内)` 为极端绝对词 `completely wiped out (彻底灭绝)`。"}]}, "d07_anaphora": [{"pronoun": "did (提前助动词)", "target": "did ... observe (= observed)", "explanation": "因句首 `Not until` 否定前置而分裂出来的过去时助动词，本身无实义，与 `observe` 合译为『才观测到』。"}, {"pronoun": "that (that had been eroded)", "target": "riverbank vegetation", "explanation": "关系代词指代先行词『河岸植被』，搭配过去完成被动 `had been eroded` 表『在捕食者回归前已经历数十年侵蚀』。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语顺译】直到顶级捕食者被系统地重新引入退化山谷／生态学家才观察到／自然放牧压力能多么迅速地把食草动物种群控制在限度内／恢复了河岸植被／那些已被侵蚀数十年的植被。", "step2_reorder": "【第二步：调序精炼】① `Not until A did B` 直接套用中文固定模具『直到 A，B 才……』；② 将句尾定语从句 `that had been eroded for decades` 前置到『河岸植被』前译为『此前已被侵蚀数十年的河岸植被』。", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`Not until...did ecologists observe` 倒装还原译出『直到……生态学家才观察到』。", "🎯 采分点 2 (0.5分)：`degraded valley` 译为『退化的山谷』（认出 degraded 退化/降级）。", "🎯 采分点 3 (0.5分)：`hold herbivore populations in check` 译为『遏制/控制食草动物种群数量』。", "🎯 采分点 4 (0.5分)：`restoring riverbank vegetation that had been eroded` 分词结果状语与过去完成被动准确译出。"]}, "d09_writing_formula": {"formula_skeleton": "Not until [关键政策/突破 A] was systematically implemented did policymakers observe how rapidly [积极机制 B] could hold [顽疾风险 C] in check, restoring [受损生态/秩序 D] that had been eroded for decades.", "imitations": [{"topic": "🏛️ 反垄断监管与数字市场公平 (考研/雅思经济科技话题)", "en": "Not until strict antitrust rules were systematically enforced did economists observe how rapidly transparent auditing could hold algorithmic price discrimination in check, restoring consumer trust that had been eroded for years.", "zh": "直到严格的反垄断规则被系统性执行，经济学家才观察到透明审计竟能如此迅速地遏制算法价格歧视，进而恢复了此前已受损多年的消费者信任。"}]}, "d10_telescoping": [{"stage": 1, "words": 8, "label": "Stage 1 · 8词正常语序主干", "en": "Ecologists did not observe the effect until later.", "added": "基础主谓宾 + not...until"}, {"stage": 2, "words": 19, "label": "Stage 2 · 19词倒装改造", "en": "Not until predators were reintroduced did ecologists observe how pressures could hold populations in check.", "added": "将 Not until 提至句首并触发 did ecologists observe 部分倒装"}, {"stage": 3, "words": 31, "label": "Stage 3 · 31词挂载分词结果状语", "en": "Not until apex predators were reintroduced into the valley did ecologists observe how rapidly grazing pressures could hold herbivore populations in check, restoring vegetation.", "added": "句尾追加 , restoring vegetation 现在分词结果状语"}, {"stage": 4, "words": 41, "label": "Stage 4 · 41词真题完全体", "en": "Not until apex predators were systematically reintroduced into the degraded valley did ecologists observe how rapidly natural grazing pressures could hold herbivore populations in check, restoring riverbank vegetation that had been eroded for decades.", "added": "补齐 degraded / systematically 及过去完成被动定语从句 that had been eroded for decades"}], "d11_discourse": {"prior_para": "【前文铺垫】描述某自然保护区因狼群等顶级掠食者消失，导致鹿群泛滥、河岸草木被啃食殆尽并引发严重水土流失。", "current_role": "【本句功能】转折实证句——用 `Not until` 倒装强烈突出『重新引入顶级捕食者』这一生态修复工程立竿见影的逆转成效。", "next_para": "【后文走向】进一步展开植被恢复后对河道水流稳定性、鸟类与海狸栖息地回归的连锁促进作用（营养级联效应 Trophic Cascade）。"}}, {"id": "LS_04_CET6_ECONOMY", "title": "🏅 经典样板 #4（CET-6 六级 & 考研英语二真题级）：独立主格结构与极端乐观情绪调和 (38词 · 独立主格 + temper/compound 熟词僻义)", "source_tag": "🏅 CET-6 六级仔细阅读 & 2027考研英语二经济管理核心样板", "word_count": 38, "char_count": 258, "difficulty": "★★★★☆ (独立主格结构 + 双熟词僻义 compound & temper)", "raw_en": "With global supply chain bottlenecks further compounded by sudden currency fluctuations, financial analysts warned that blind optimism about short-term stimulus packages must be tempered with structural reforms designed to weather prolonged market volatility.", "google_raw_zh": "随着全球供应链瓶颈因突然的汇率波动而进一步加剧，金融分析师警告称，对短期刺激计划的盲目乐观情绪必须通过旨在抵御长期市场波动的结构性改革来缓和。", "google_defect_diagnosis": "未拆解句首 `With + 名词 + 过去分词 (compounded)` 独立主格结构，且未串联 `compound (K07 叠合加剧/雪上加霜)`、`temper (K09 淬火调和/节制)`、`weather (K10 经受住/渡过风暴)` 三大核心一词一义多义词。", "d01_prosody": {"chunked_en": "[1] ●With global supply chain ●bottlenecks / further ●compounded by sudden currency ●fluctuations, || [2] financial ●analysts warned that / blind ●optimism about short-term stimulus packages || [3] must be ●tempered with structural ●reforms / ●designed to ●weather / prolonged market ●volatility.", "breath_groups": [{"chunk": "With global supply chain bottlenecks further compounded by sudden currency fluctuations,", "zh": "由于全球供应链瓶颈因突如其来的汇率波动而进一步雪上加霜，", "role": "🟨 With + 名词 + 过去分词 (独立主格作原因/背景状语)", "pause_after": "|| (长停顿 0.45s · 背景状语结束，进入主句主谓 financial analysts warned)"}, {"chunk": "financial analysts warned that blind optimism about short-term stimulus packages", "zh": "金融分析师警告称，对于短期刺激方案的盲目乐观情绪", "role": "🟦 主句主谓 + that 宾语从句主语", "pause_after": "/ (微停顿 0.25s · 引出宾语从句核心情态被动谓语 must be tempered)"}, {"chunk": "must be tempered with structural reforms designed to weather prolonged market volatility.", "zh": "必须用旨在抵御长期市场动荡的结构性改革加以审慎调和。", "role": "🟪 情态被动谓语 + 过去分词后置定语 (designed to weather...)", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "Analysts warned that blind optimism must be tempered with reforms.", "trunk_zh": "【极简九词主干】[分析师] (S) + [警告称] (V) + [盲目乐观必须用改革加以调和节制] (O: 宾语从句)。", "layers": [{"level": "L1 With 独立主格伴随/原因状语 (With Absolute Construction)", "color": "#d97706", "segment": "With + [global supply chain bottlenecks] (宾语) + [further compounded by sudden currency fluctuations] (过去分词宾补)", "function": "`With + n. + done` 独立主格结构，浓缩了一个完整的被动原因状语从句（因为瓶颈被汇率波动进一步加剧）。"}, {"level": "L2 主句 + 宾语从句主干 (Main Clause & Object Clause)", "color": "#2563eb", "segment": "financial analysts warned + that blind optimism (about short-term stimulus packages) must be tempered (with structural reforms)", "function": "`be tempered with...`（K09 刚柔淬火调和：用……来中和/节制过度的乐观）。"}, {"level": "L3 过去分词后置定语 + 不定式目的 (Participle Post-Modifier)", "color": "#10b981", "segment": "designed (to weather prolonged market volatility)", "function": "过去分词 `designed` 修饰 `reforms`（相当于 `which are designed...`），其中 `weather` 作动词表『顶住风浪渡过』。"}]}, "d05_collocations": [{"chunk": "With [ problem A ] further compounded by [ factor B ]", "zh": "随着问题A因因素B而进一步雪上加霜（独立主格满分起句）", "exam_use": "图表作文/议论文开篇交代复杂严峻背景的王牌结构"}, {"chunk": "blind optimism about short-term stimulus", "zh": "对短期刺激政策的盲目乐观", "exam_use": "经济评论高频名词短语"}, {"chunk": "be tempered with...", "zh": "用……加以调和/节制（宽严相济/冷热调和）", "exam_use": "temper (K09) 最核心考场搭配"}, {"chunk": "structural reforms designed to weather...", "zh": "旨在渡过/抵御……的结构性改革", "exam_use": "weather (K10 动词：经受住风暴/危机) + prolonged volatility (长期动荡)"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【三词连环熟词僻义】：一句之内密集考查 `compound (v. 使恶化/加剧)`、`temper (v. 调和/缓和)`、`weather (v. 经受住/渡过)` 三个最高频熟词僻义！", "🚨 信号 2【must be tempered with 作者建议靶心】：阅读题问作者或分析师的主张时，`must` 之后的内容（需要能够抵御长期动荡的结构性改革，而非盲目依赖短期刺激）永远是正确选项！"], "mcq_question": "What do financial analysts suggest in the face of worsening supply chain and currency pressures?", "mcq_options": [{"opt": "A", "text": "Expanding short-term stimulus packages immediately to boost market confidence.", "is_correct": false, "analysis": "❌ 原文明确批评了对短期刺激方案的盲目乐观 (`blind optimism about short-term stimulus`)。"}, {"opt": "B", "text": "Balancing short-term expectations with deep institutional reforms capable of enduring long-term instability.", "is_correct": true, "analysis": "✅ `Balancing...with` 对应 `be tempered with`；`deep institutional reforms` 对应 `structural reforms`；`enduring long-term instability` 完美替换 `weather prolonged market volatility`！"}, {"opt": "C", "text": "Waiting for currency fluctuations to subside naturally before introducing any reform.", "is_correct": false, "analysis": "❌ 无中生有（原文未主张消极等待汇率自然平息）。"}, {"opt": "D", "text": "Predicting weather patterns more accurately to protect global shipping routes.", "is_correct": false, "analysis": "❌ 经典望文生义陷阱：把动词 `weather (渡过危机)` 误当成名词『天气预报 (weather patterns)』！"}]}, "d07_anaphora": [{"pronoun": "compounded (非谓语过去分词)", "target": "global supply chain bottlenecks (被动承受者)", "explanation": "因瓶颈是『被加剧』，故 `With` 结构中必须用过去分词 `compounded` 而非 `compounding`。"}, {"pronoun": "designed (后置分词)", "target": "structural reforms", "explanation": "相当于定语从句 `which are designed to...`，修饰前面的『结构性改革』。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语顺译】随着全球供应链瓶颈被突发汇率波动进一步加剧／金融分析师警告说／对短期刺激包的盲目乐观／必须用结构性改革加以调和／那些被设计用来渡过长期市场动荡的改革。", "step2_reorder": "【第二步：调序精炼】① `With + n. + done` 译为原因/背景分句『由于全球供应链瓶颈因突发汇率波动而进一步雪上加霜』；② 将 `designed to weather...` 前置修饰『结构性改革』。", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`further compounded by` 准确译为『因……而进一步加剧/恶化』。", "🎯 采分点 2 (0.5分)：`blind optimism about short-term stimulus packages` 译为『对短期刺激计划的盲目乐观』。", "🎯 采分点 3 (0.5分)：`must be tempered with` 译为『必须用……加以调和/节制』。", "🎯 采分点 4 (0.5分)：`designed to weather prolonged market volatility` 译为『旨在抵御/渡过长期市场波动的』。 "]}, "d09_writing_formula": {"formula_skeleton": "With [存量挑战 A] further compounded by [突发冲击 B], experts warn that blind optimism about [短期权宜之计 C] must be tempered with [治本之策 D] designed to weather [长期风险 E].", "imitations": [{"topic": "🔋 新能源转型与电网韧性 (六级/雅思科技能源话题)", "en": "With aging power grids further compounded by extreme summer heatwaves, energy planners warn that blind optimism about rapid solar expansion must be tempered with storage infrastructure designed to weather prolonged peak-load fluctuations.", "zh": "由于老化的电网因夏季极端热浪而进一步承压，能源规划者警告称，对光伏快速扩张的盲目乐观必须用旨在抵御长期峰值负荷波动的储能基建加以调和。"}]}, "d10_telescoping": [{"stage": 1, "words": 8, "label": "Stage 1 · 8词主干", "en": "Analysts warned that optimism must be tempered.", "added": "最简主谓 + 宾语从句被动核"}, {"stage": 2, "words": 19, "label": "Stage 2 · 19词扩展介宾修饰", "en": "Financial analysts warned that blind optimism about stimulus packages must be tempered with structural reforms.", "added": "补充 about 短语与 with 施事工具短语"}, {"stage": 3, "words": 28, "label": "Stage 3 · 28词挂载分词后置定语", "en": "Financial analysts warned that blind optimism about short-term stimulus packages must be tempered with structural reforms designed to weather prolonged market volatility.", "added": "句尾追加 designed to weather... 过去分词后置定语链"}, {"stage": 4, "words": 38, "label": "Stage 4 · 38词真题完全体", "en": "With global supply chain bottlenecks further compounded by sudden currency fluctuations, financial analysts warned that blind optimism about short-term stimulus packages must be tempered with structural reforms designed to weather prolonged market volatility.", "added": "句首挂载 With + 名词 + compounded 独立主格背景状语"}], "d11_discourse": {"prior_para": "【前文铺垫】回顾各国在疫情或危机初期推出大规模短期财政刺激后一度引发股市短暂反弹。", "current_role": "【本句功能】冷水预警与对策升华句——指出在供应链与汇率双重冲击下，短期强心针已不够用，必须转向长效结构性改革。", "next_para": "【后文走向】具体拆解结构性改革的三大支柱（如供应链多元化、汇率风险对冲机制与产业升级）。"}}, {"id": "LS_05_KAOYAN_TRANSLATION", "title": "📜 历年考研真题 #5（考研英语一翻译 Part C 经典母型）：形式主语 + 双破折号插入语 + 被动主语从句 (34词)", "source_tag": "🎓 历年考研英语一翻译真题高频母型（科学史与实证精神）· 专治『破折号插入语打断主干』", "word_count": 34, "char_count": 225, "difficulty": "★★★★★ (考研英一翻译 2.0 分满贯决胜句)", "raw_en": "It is a tribute to the resilience of empirical inquiry — and a measure of its institutional maturity — that hypotheses once dismissed as heresy are now routinely subjected to rigorous replication.", "google_raw_zh": "曾被视为异端的假说如今经常受到严格的重复验证，这既是对实证研究韧性的赞美，也是其制度成熟度的衡量标准。", "google_defect_diagnosis": "直出译文隐藏了『It is A — and B — that C』形式主语框架与双破折号并列插入语，且未点破 `dismissed as heresy`（斥为异端）与 `subjected to`（接受/经受）两大考研必考词块。", "d01_prosody": {"chunked_en": "[1] It is a ●tribute / to the ●resilience of empirical ●inquiry || [2] — and a ●measure / of its institutional ●maturity — || [3] that ●hypotheses / once ●dismissed as ●heresy || [4] are now ●routinely subjected / to ●rigorous ●replication.", "breath_groups": [{"chunk": "It is a tribute to the resilience of empirical inquiry", "zh": "这既是对实证探究生命力/韧性的一曲赞歌", "role": "🟦 形式主语 + 表语核 1", "pause_after": "|| (破折号前悬停 0.40s)"}, {"chunk": "— and a measure of its institutional maturity —", "zh": "——同时也是衡量其制度成熟度的标尺——", "role": "🟨 双破折号并列插入语 (表语核 2)", "pause_after": "|| (破折号收束换气 0.45s)"}, {"chunk": "that hypotheses once dismissed as heresy", "zh": "即：那些曾一度被斥为异端邪说的科学假说", "role": "🟪 真正主语从句主语 + 过去分词后置定语", "pause_after": "/ (主谓分界微停 0.25s)"}, {"chunk": "are now routinely subjected to rigorous replication.", "zh": "如今已常规性地接受严苛的重复实验验证。", "role": "🟥 真正主语从句被动谓语核", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "It is a tribute (and a measure) that hypotheses are subjected to replication.", "trunk_zh": "【极简主干】假说接受重复验证，这是一种赞颂（也是一种衡量标尺）。", "layers": [{"level": "L1 形式主语与双表语核 (Dummy Subject + Twin Predicatives)", "color": "#2563eb", "segment": "It is a tribute to... — and a measure of... —", "function": "`It` 为先行形式主语，双破折号内部补充第二个并列表语 `a measure of...`。"}, {"level": "L2 真正主语从句 (Extraposed Subject Clause)", "color": "#d97706", "segment": "that hypotheses ... are now routinely subjected to rigorous replication", "function": "`that` 引导真正主语从句，因主语从句长达 14 词，故后置以符合英语尾重原则。"}, {"level": "L3 过去分词后置定语 (Participle Post-Modifier)", "color": "#10b981", "segment": "(which were) once dismissed as heresy", "function": "过去分词短语修饰 `hypotheses`，表『曾被当作异端邪说加以摒弃的』。"}]}, "d05_collocations": [{"chunk": "It is a tribute to... that...", "zh": "……是对……的赞颂/有力证明", "exam_use": "考研翻译与大作文评价科学/制度成就的满分起手式"}, {"chunk": "once dismissed as...", "zh": "曾一度被斥为/被轻视为……", "exam_use": "学术史对比古今态度转变的王牌分词短语"}, {"chunk": "be routinely subjected to...", "zh": "常规性地接受/经受……（检验或审视）", "exam_use": "subject 作动词：使服从/使经受 (K04 受力生发)"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【双破折号插入语】：考研阅读与翻译常在双破折号内藏并列同义线索（`resilience` 对应 `institutional maturity`）。", "🚨 信号 2【古今时间对比 once vs now】：`once dismissed as heresy` 与 `now routinely subjected to rigorous replication` 构成强烈今昔对比，必考态度转变题！"], "mcq_question": "What does the routine replication of previously controversial hypotheses demonstrate?", "mcq_options": [{"opt": "A", "text": "The robust vitality and institutional maturity of scientific inquiry.", "is_correct": true, "analysis": "✅ `robust vitality` 对应 `resilience`；`institutional maturity of scientific inquiry` 原词复现！"}, {"opt": "B", "text": "The complete elimination of unorthodox theories from modern academia.", "is_correct": false, "analysis": "❌ 与原文相反，原文强调昔日异端假说如今得以接受严格检验而非被彻底抹杀。"}]}, "d07_anaphora": [{"pronoun": "It (句首形式主语)", "target": "that hypotheses once dismissed as heresy are now...", "explanation": "`It` 本身无实义，指向破折号之后的 `that` 真正主语从句。"}, {"pronoun": "its (破折号内物主代词)", "target": "empirical inquiry (实证探究)", "explanation": "指代前文单数核心名词短语 `empirical inquiry`。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语顺译】这是对实证探究韧性的赞颂／——也是其制度成熟度的衡量——／即曾被斥为异端的假说／如今常规性地接受严格重复验证。", "step2_reorder": "【第二步：调序精炼】汉语习惯『先事后评』：可将 `that` 真正主语从句提至句首翻译，再以『这既证明了……，也衡量了……』收尾。", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`a tribute to the resilience of empirical inquiry` 译为『对实证探究韧性/生命力的赞颂』。", "🎯 采分点 2 (0.5分)：`a measure of its institutional maturity` 译为『衡量其制度成熟度的标尺』。", "🎯 采分点 3 (0.5分)：`once dismissed as heresy` 译为『曾被斥为/视为异端邪说的』。", "🎯 采分点 4 (0.5分)：`routinely subjected to rigorous replication` 译为『常规性地接受严格的重复验证』。"]}, "d09_writing_formula": {"formula_skeleton": "It is a tribute to [核心品质 A] — and a measure of [深层进步 B] — that [昔日痛点 C] are now routinely [正向机制 D].", "imitations": [{"topic": "⚖️ 法治与生态治理 (考研大作文/雅思 Task 2)", "en": "It is a tribute to the evolution of environmental jurisprudence — and a measure of civic awareness — that ecological damages once ignored as externalities are now routinely subjected to strict judicial accountability.", "zh": "曾被当作外部性而忽视的生态破坏如今常规性地接受严格司法追责，这既是对环境法学演进的赞颂，也是公民意识提升的体现。"}]}, "d10_telescoping": [{"stage": 1, "words": 9, "label": "Stage 1 · 9词主干", "en": "It is a tribute that hypotheses are subjected to replication.", "added": "It is... that... 形式主语最简骨架"}, {"stage": 2, "words": 18, "label": "Stage 2 · 18词扩展介宾与分词", "en": "It is a tribute to empirical inquiry that hypotheses once dismissed as heresy are subjected to rigorous replication.", "added": "挂载 once dismissed as heresy 过去分词后置定语"}, {"stage": 3, "words": 26, "label": "Stage 3 · 26词补齐抽象名词修饰", "en": "It is a tribute to the resilience of empirical inquiry that hypotheses once dismissed as heresy are now routinely subjected to rigorous replication.", "added": "注入 resilience 与 routinely 时间频率副词"}, {"stage": 4, "words": 34, "label": "Stage 4 · 34词真题完全体", "en": "It is a tribute to the resilience of empirical inquiry — and a measure of its institutional maturity — that hypotheses once dismissed as heresy are now routinely subjected to rigorous replication.", "added": "嵌入双破折号 — and a measure of... — 并列插入语"}], "d11_discourse": {"prior_para": "【前文铺垫】回顾科学史上许多颠覆性发现在提出之初曾遭到主流学界的排斥与冷遇。", "current_role": "【本句功能】段落总结升华句——礼赞现代科学制度用『可重复实验验证』取代了昔日的教条审判。", "next_para": "【后文走向】举例说明某一具体学科（如量子物理或表观遗传学）如何通过重复验证确立新范式。"}}, {"id": "LS_06_IELTS_DOUBLE_NEGATION", "title": "🌍 历年雅思真题 #6（剑桥雅思阅读 Passage 3 经典母型）：Far from 隐性否定 + make/render 复合宾语后置 (31词)", "source_tag": "🌍 剑雅阅读 8.5 分长难句母型（AI 与人类深度阅读素养）· 专治『Far from 极性反译与宾语后置』", "word_count": 31, "char_count": 228, "difficulty": "★★★★★ (IELTS Reading YES/NO/NOT GIVEN 极性杀手句)", "raw_en": "Far from diminishing the necessity of foundational literacy, the proliferation of generative algorithms has rendered the capacity to critically evaluate textual coherence more indispensable than ever.", "google_raw_zh": "生成式算法的普及非但没有削弱基础读写能力的必要性，反而使批判性评估文本连贯性的能力比以往任何时候都更加不可或缺。", "google_defect_diagnosis": "直出译文未揭示 `render + 宾语 (the capacity... coherence) + 宾补 (more indispensable than ever)` 的宾语扩张结构，考生极易在长不定式定语中迷失宾语补足语。", "d01_prosody": {"chunked_en": "[1] ●Far from diminishing / the ●necessity of foundational ●literacy, || [2] the ●proliferation / of generative ●algorithms || [3] has ●rendered the ●capacity / to critically ●evaluate textual ●coherence || [4] ●more ●indispensable / than ●ever.", "breath_groups": [{"chunk": "Far from diminishing the necessity of foundational literacy,", "zh": "非但没有削弱基础读写素养的必要性，", "role": "🟨 负向否定伴随状语 (Far from + V-ing)", "pause_after": "|| (逗号主从停顿 0.40s)"}, {"chunk": "the proliferation of generative algorithms", "zh": "生成式算法的迅猛普及", "role": "🟦 主句核心主语短语", "pause_after": "/ (主谓衔接微停 0.20s)"}, {"chunk": "has rendered the capacity to critically evaluate textual coherence", "zh": "反而使得『批判性评估文本连贯性的能力』", "role": "🟪 谓语动词 rendered + 复合长宾语 (含不定式定语)", "pause_after": "/ (宾语与宾补分界 0.25s)"}, {"chunk": "more indispensable than ever.", "zh": "变得比以往任何时候都更加不可或缺。", "role": "🟥 形容词比较级宾语补足语", "pause_after": "◎ (句末降调收束)"}]}, "d02_syntax_tree": {"trunk_9words": "The proliferation has rendered the capacity more indispensable.", "trunk_zh": "【极简主干】（算法）普及使得（评估）能力变得更加不可或缺。", "layers": [{"level": "L1 句首隐性否定状语 (Negative Prepositional Gerund)", "color": "#d97706", "segment": "Far from diminishing the necessity of foundational literacy,", "function": "`Far from doing` 表『非但没有做……，反而……』，强烈预示主句走向正向强化。"}, {"level": "L2 主句主谓宾补骨架 (SVOC Core)", "color": "#2563eb", "segment": "the proliferation ... has rendered [the capacity ...] [more indispensable than ever]", "function": "`render + 宾语 + 形容词宾补`（使……变得……），考研与雅思阅读最高频致使结构。"}, {"level": "L3 不定式后置定语嵌入宾语 (Infinitive Post-Modifier)", "color": "#10b981", "segment": "to critically evaluate textual coherence", "function": "修饰宾语 `the capacity`，隔开了宾语核与末尾的宾补 `more indispensable`。"}]}, "d05_collocations": [{"chunk": "Far from diminishing...", "zh": "非但没有削弱/减少……（反而……）", "exam_use": "驳论文反驳片面观点的王牌句首状语"}, {"chunk": "the proliferation of...", "zh": "……的激增/迅猛扩散", "exam_use": "雅思 Task 2 与考研科技话题替换 rapid spread 的高分名词"}, {"chunk": "render [A] more indispensable than ever", "zh": "使 A 变得比以往任何时候都更加不可或缺", "exam_use": "render + adj. 替换 make + adj. 的学术黄金搭配"}], "d06_examiner_radar": {"signals": ["🚨 信号 1【Far from + V-ing 强否定】：剑雅阅读判断题一旦原文出现 `Far from`，题目若写成 `has reduced the need for...` 必选 **FALSE / NO**！", "🚨 信号 2【indispensable 双重否定表强烈肯定】：`in- (不) + dispensable (可省却的) = 不可或缺的 (essential/vital)`。"], "mcq_question": "According to the sentence, how has the rise of generative AI affected basic reading and critical evaluation skills?", "mcq_options": [{"opt": "A", "text": "It has made critical reading and evaluation skills even more vital than before.", "is_correct": true, "analysis": "✅ `made... even more vital than before` 完美同义替换 `rendered... more indispensable than ever`！"}, {"opt": "B", "text": "It has gradually replaced the need for human foundational literacy.", "is_correct": false, "analysis": "❌ 与句首 `Far from diminishing the necessity of foundational literacy` 极性完全相反！"}]}, "d07_anaphora": [{"pronoun": "diminishing (句首动名词逻辑主语)", "target": "the proliferation of generative algorithms", "explanation": "句首非谓语 `Far from diminishing...` 的逻辑主语与主句主语严格一致。"}], "d08_translation_rubric": {"step1_linear": "【第一步：英语顺译】非但没有削弱基础读写能力的必要性／生成式算法的普及／已经使得批判性评估文本连贯性的能力／比以往任何时候都更加不可或缺。", "step2_reorder": "【第二步：调序精炼】将主语『生成式算法的普及』提至句首统领全句：『生成式算法的普及非但没有削弱……，反而使……变得比以往更加不可或缺。』", "step3_checkpoints": ["🎯 采分点 1 (0.5分)：`Far from diminishing` 准确译为『非但没有削弱/远未降低』。", "🎯 采分点 2 (0.5分)：`proliferation of generative algorithms` 译为『生成式算法的普及/激增』。", "🎯 采分点 3 (0.5分)：`rendered the capacity to critically evaluate...` 译为『使批判性评估……的能力』。", "🎯 采分点 4 (0.5分)：`more indispensable than ever` 译为『比以往任何时候都更加不可或缺』。"]}, "d09_writing_formula": {"formula_skeleton": "Far from diminishing the necessity of [传统核心素养 A], the proliferation of [新兴技术 B] has rendered the capacity to [高阶能力 C] more indispensable than ever.", "imitations": [{"topic": "🎓 AI 时代的高等教育 (考研大作文/雅思教育话题)", "en": "Far from diminishing the necessity of independent philosophical reflection, the proliferation of automated search tools has rendered the capacity to formulate original questions more indispensable than ever.", "zh": "自动化检索工具的普及非但没有削弱独立哲学思考的必要性，反而使提出原创性问题的能力变得比以往任何时候都更加不可或缺。"}]}, "d10_telescoping": [{"stage": 1, "words": 8, "label": "Stage 1 · 8词主干", "en": "Proliferation has rendered the capacity more indispensable.", "added": "SVOC 最简致使主干"}, {"stage": 2, "words": 15, "label": "Stage 2 · 15词补充主语与比较", "en": "The proliferation of generative algorithms has rendered the capacity more indispensable than ever.", "added": "补齐 of generative algorithms 与 than ever"}, {"stage": 3, "words": 22, "label": "Stage 3 · 22词挂载不定式定语", "en": "The proliferation of generative algorithms has rendered the capacity to critically evaluate textual coherence more indispensable than ever.", "added": "在宾语后插入 to critically evaluate textual coherence"}, {"stage": 4, "words": 31, "label": "Stage 4 · 31词真题完全体", "en": "Far from diminishing the necessity of foundational literacy, the proliferation of generative algorithms has rendered the capacity to critically evaluate textual coherence more indispensable than ever.", "added": "句首挂载 Far from diminishing... 隐性否定状语"}], "d11_discourse": {"prior_para": "【前文铺垫】提及公众普遍担忧 ChatGPT 等生成式 AI 会导致学生丧失基础读写与阅读分析能力。", "current_role": "【本句功能】强力驳论转折句——直接推翻悲观论调，确立『AI 时代人类高阶批判性阅读反而更重要』的核心论点。", "next_para": "【后文走向】解释为什么需要人类评估文本连贯性（因为算法可能产生看似流畅实则逻辑幻觉的内容）。"}}], "weakness_drills": {"W01_PARTICIPLE_POLYSEMY": {"code": "W01", "title": "过去分词屈折变形与熟词僻义误判 (如 borne 误译为『出生』、harbor 误译为『港口』、temper 误译为『脾气』)", "strategy": "遇到过去分词被动态 (be + V-ed + by) 或熟词僻义动词时，先通过施受事主客体判断动作方向，切勿按初中第一释义硬套。", "target_sentence_id": "LS_04_CET6_ECONOMY", "drill_en": "Were the financial burdens borne by small enterprises to be compounded by abrupt credit tightening, even the most resilient local economies would struggle to weather the downturn.", "drill_zh": "倘若小微企业所承担的财务负担因信贷骤然收紧而雪上加霜，即便最具韧性的地方经济也将难以渡过衰退难关。", "drill_focus": "专项训练：borne by (由…承担) + compounded by (因…加剧) + weather (渡过危机)"}, "W02_PARALLEL_NOUN_CLAUSE": {"code": "W02", "title": "主语从句与并列双表语从句逻辑极性失焦 (What makes... is not merely that A, but that B)", "strategy": "先抓主系表主干『What makes X difficult is not A, but B』，明确 not merely 是陪衬让步，but that 之后才是命题重心。", "target_sentence_id": "LS_08_BIZ_ECOLOGY", "drill_en": "What makes the transition toward renewable grids so contentious is not merely that legacy infrastructure requires massive capital outlay, but that the short-term tariff surcharges are often shouldered unevenly by low-income households.", "drill_zh": "围绕可再生电网转型的争论之所以如此激烈，不仅在于老旧基础设施需要巨额资本投入，更在于短期电价附加费往往不均衡地由低收入家庭承担。", "drill_focus": "专项训练：What makes... is not merely that..., but that... 同构骨架盲译复盘"}, "W03_INVERSION_NEGATION": {"code": "W03", "title": "否定副词置首部分倒装或隐性双重否定极性反译 (Not until... did... / Far from...)", "strategy": "见到 Not until / Hardly / Scarcely 居首且后接助动词 did/had/would，立即将『直到…才…』还原为正常主谓语序再顺译。", "target_sentence_id": "LS_03_IELTS_INVERSION", "drill_en": "Not until longitudinal satellite telemetry revealed the accelerated thawing of permafrost did climate modelers realize that carbon feedback loops had been systematically underestimated.", "drill_zh": "直到长期的卫星遥测数据揭示出永久冻土加速融化，气候建模学者才意识到碳反馈循环一直被系统性地低估了。", "drill_focus": "专项训练：Not until... did + 主语 + 动词原形（直到…才…）部分倒装结构"}, "W04_POST_MODIFIER_ORDER": {"code": "W04", "title": "长定语从句与后置不定式修饰链语序欧化或挂靠错位 (those who have the least power to influence...)", "strategy": "超过 8 个词的 who/which/in which 定语从句，在汉译时可采用『前置打包为“……的人群”』或『拆句独立成句』。", "target_sentence_id": "LS_07_KAOYAN_LAW", "drill_en": "Were regulatory frameworks to lag persistently behind algorithmic deployment, the very mechanisms through which citizens seek redress for automated bias would be rendered largely illusory.", "drill_zh": "倘若监管框架持续滞后于算法部署，公民借以针对自动化偏见寻求救济的机制本身就将在很大程度上形同虚设。", "drill_focus": "专项训练：Were... to... 虚拟倒装 + through which 介词定语从句调序"}, "W05_INSERTION_APPOSITIVE": {"code": "W05", "title": "形式主语/双破折号插入语阻断主干连贯性 (It is a tribute to... — and a measure of... — that...)", "strategy": "阅读与翻译时先用括号跳过双破折号 `— ... —` 插入语，直接将 `It is... that...` 真正主语从句接通。", "target_sentence_id": "LS_05_KAOYAN_TRANSLATION", "drill_en": "It is a tribute to the resilience of empirical inquiry — and a measure of its institutional maturity — that hypotheses once dismissed as heresy are now routinely subjected to rigorous replication.", "drill_zh": "曾被斥为异端邪说的假说如今常规性地接受严格重复验证，这既是对实证探究韧性的赞颂，也是其制度成熟度的体现。", "drill_focus": "专项训练：It is... — 插入语 — that... 考研翻译高频拆句逆译法"}}, "morpheme_kb": {"debate": {"split": "de- (彻底/向下) + bat (击打/交锋) + -e", "root": "bat /ebat (to beat 击打)", "cognates": "combat (战斗), batter (猛击), battalion (军营), abate (减轻)"}, "artificial": {"split": "art (技艺/人为) + -i- + fic (make 制造) + -ial (形容词后缀)", "root": "art (skill) + fac/fic (to make)", "cognates": "artifact (人工制品), magnificent (宏伟的), superficial (表面的)"}, "intelligence": {"split": "inter/intel- (在…之间) + lig (choose/gather 选择/采集) + -ence (名词后缀)", "root": "leg / lig / lect (to choose, gather 选拔/理解)", "cognates": "intellectual (知识分子), eligible (合格的), collect (收集), neglect (忽视)"}, "difficult": {"split": "dif- (dis- 否定/偏离) + fic (fac 容易做) + -ult", "root": "fac / fic (to do, make 做)", "cognates": "facilitate (促进/使容易), faculty (能力/全体教员), efficient (高效的)"}, "technology": {"split": "techno- (技艺/技术) + -logy (学科/体系)", "root": "techno (art, skill 技艺)", "cognates": "technique (技法), technical (技术的), biotechnology (生物技术)"}, "evolving": {"split": "e- (ex- 向外) + volv (roll 滚动/展开) + -ing (现在分词)", "root": "volv / volut (to roll 滚动/卷)", "cognates": "evolve (演进), involve (卷入/涉及), revolve (旋转), revolution (革命), volume (卷/体积)"}, "regulators": {"split": "reg- (rule/straight 划直/规矩) + -ul- + -ator (施事者/机构) + -s", "root": "reg / rect (to rule, straight 统治/校准)", "cognates": "regulate (监管/调节), regular (规则的), regime (政权/体制), correct (纠正), direct (指导)"}, "respond": {"split": "re- (back 回) + spond (pledge/promise 庄重承诺/应答)", "root": "spond / spons (to pledge, answer 允诺/回应)", "cognates": "response (回应), responsible (负责的), correspond (对应/通信), sponsor (发起人/赞助)"}, "consequences": {"split": "con- (together 共同) + sequ (follow 紧随) + -ence (名词后缀) + -s", "root": "sequ / secut (to follow 跟随)", "cognates": "subsequent (随后的), sequence (序列), pursue (追寻), consecutive (连续的), prosecute (起诉)"}, "borne": {"split": "bear (承重/负荷) + -ne (不规则过去分词)", "root": "ber / pher (to carry, bear 承载/生育)", "cognates": "bear (承担/忍受), burden (重担), unbearable (难以承受的), transfer (转移), fertile (肥沃的/多产的)"}, "disproportionately": {"split": "dis- (偏离/不) + pro- (向前/按) + port (part/share 份额) + -ion + -ate + -ly", "root": "port (part, share 份额/部分)", "cognates": "proportion (比例/均衡), portion (一部分), apportion (分摊), impartial (公正无偏的)"}, "influence": {"split": "in- (into 流入) + flu (flow 流动) + -ence (名词后缀)", "root": "flu / flux (to flow 流动)", "cognates": "fluent (流利的), fluctuate (波动), affluent (富裕的), influenza (流感), influx (涌入)"}, "rules": {"split": "rul (reg 规矩/标尺) + -e + -s", "root": "reg / rul (straight, rule 标尺/统治)", "cognates": "ruler (统治者/直尺), overrule (驳回/否决), unruly (不受约束的)"}}, "participle_kb": {"borne": {"lemma": "bear /beə(r)/", "form_type": "过去分词 (Past Participle · 被动核心谓语 to be borne)", "inflection": "bear (原形) ➔ bore (过去式) ➔ borne (过去分词: 承担/承受/携带) vs born (仅用于 be born 出生)", "syntactic_role": "与助动词 to be 构成不定式被动语态 (to be borne by...)，表『后果由……来承担』", "exam_trap": "⚠️ 考场头号陷阱：切勿将 borne (承担/承受，后常接 by) 误认成 born (出生) 或 bourne (界限)！IELTS/考研完形与翻译高频采分点。"}, "evolving": {"lemma": "evolve /ɪˈvɒlv/", "form_type": "现在分词 (Present Participle · 进行态谓语核心 is evolving)", "inflection": "evolve (原形) ➔ evolved (过去式/过去分词) ➔ evolving (现在分词)", "syntactic_role": "在第一个 that 表语从句中与 is 构成现在进行时，生动刻画 AI 技术『正在持续动态滚雪球演进』的过程感", "exam_trap": "⚠️ 熟词与词性辨析：evolving 作定语时表『正在演变的 (an evolving crisis)』，而 evolved 表『已进化成熟的』。"}, "getting": {"lemma": "get /ɡet/", "form_type": "动名词 (Gerund · 介词宾语 of getting it wrong)", "inflection": "get (原形) ➔ got (过去式) ➔ gotten/got (过去分词) ➔ getting (双写 t + ing 动名词/现在分词)", "syntactic_role": "置于介词 of 之后构成动名词短语 `of getting it wrong`，作后置定语具体解释 `the consequences` 的内涵（即：如果把 AI 监管搞砸了的后果）", "exam_trap": "⚠️ 翻译难点：英文用抽象名词 + of doing (`the consequences of getting it wrong`)，中文翻译必须转化为假设条件分句『一旦决策失误 / 一旦把事情搞砸，其后果……』！"}, "to influence": {"lemma": "influence /ˈɪnfluəns/", "form_type": "动词不定式 (Infinitive · 后置定语修饰抽象名词 power)", "inflection": "to + influence (动词原形)", "syntactic_role": "紧跟在最高级名词短语 `the least power` 之后作后置定语，限定『什么样的权力/能力』——即『去左右/影响规则制定的话语权』", "exam_trap": "⚠️ 高频搭配定律：`power / ability / capacity / right / opportunity + to do sth.` 永远用不定式作后置定语，不可误用 of doing！"}}};
